17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.service.CityOwnerLimitException;
34	import org.springframework.samples.petclinic.service.DuplicateHouseholdException;
35	import org.springframework.samples.petclinic.service.DuplicateTelephoneException;
36	import org.springframework.security.access.AccessDeniedException;
37	import org.springframework.validation.BindingResult;
38	import org.springframework.validation.FieldError;
39	import org.springframework.web.bind.MethodArgumentNotValidException;
40	import org.springframework.web.bind.annotation.ControllerAdvice;
41	import org.springframework.web.bind.annotation.ExceptionHandler;
42	import org.springframework.web.bind.annotation.ResponseBody;
43	
44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
94	     *
95	     * @param e The {@link Exception} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
98	     */
99	    @ExceptionHandler(Exception.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
102	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
103	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
104	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
105	        return ResponseEntity.status(status).body(detail);
106	    }
107	
108	    /**
109	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
110	     * method returns a 404 Not Found status if an entity does not exist.
111	     *
112	     * @param e The {@link DataIntegrityViolationException} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
115	     */
116	    @ExceptionHandler(DataIntegrityViolationException.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
119	        logger.warn("Data integrity violation at {} {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            e.getMessage());
123	        logger.debug("Data integrity violation stacktrace", e);
124	        HttpStatus status = HttpStatus.NOT_FOUND;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles {@link DuplicateTelephoneException}, raised when an owner is created or updated with a
131	     * normalized telephone number already used by another owner. Returns a 409 Conflict status.
132	     *
133	     * @param e The {@link DuplicateTelephoneException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
136	     */
137	    @ExceptionHandler(DuplicateTelephoneException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
140	        logger.warn("Duplicate telephone at {} {}: {}",
141	            request.getMethod(),
142	            request.getRequestURI(),
143	            e.getMessage());
144	        HttpStatus status = HttpStatus.CONFLICT;
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link DuplicateHouseholdException}, raised when an owner is created with the same
151	     * lastName and address (compared case-insensitively with collapsed whitespace) as an existing
152	     * owner without acknowledging the shared household. Returns a 409 Conflict status.
153	     *
154	     * @param e The {@link DuplicateHouseholdException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
157	     */
158	    @ExceptionHandler(DuplicateHouseholdException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
161	        logger.warn("Duplicate household at {} {}: {}",
162	            request.getMethod(),
163	            request.getRequestURI(),
164	            e.getMessage());
165	        HttpStatus status = HttpStatus.CONFLICT;
166	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
167	        return ResponseEntity.status(status).body(detail);
168	    }
169	
170	    /**
171	     * Handles {@link CityOwnerLimitException}, raised when an owner is created in a city that
172	     * already contains the maximum number of owners. Returns a 409 Conflict status.
173	     *
174	     * @param e The {@link CityOwnerLimitException} to be handled
175	     * @param request {@link HttpServletRequest} object referring to the current request.
176	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
177	     */
178	    @ExceptionHandler(CityOwnerLimitException.class)
179	    @ResponseBody
180	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitException(CityOwnerLimitException e, HttpServletRequest request) {
181	        logger.warn("City owner limit reached at {} {}: {}",
182	            request.getMethod(),
183	            request.getRequestURI(),
184	            e.getMessage());
185	        HttpStatus status = HttpStatus.CONFLICT;
186	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
187	        return ResponseEntity.status(status).body(detail);
188	    }
189	
190	    /**
191	     * Handles exception thrown by Bean Validation on controller methods parameters
192	     *
193	     * @param e The {@link MethodArgumentNotValidException} to be handled
194	     * @param request {@link HttpServletRequest} object referring to the current request.
195	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
196	     */
197	    @ExceptionHandler(MethodArgumentNotValidException.class)
198	    @ResponseBody
199	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
200	        HttpStatus status = HttpStatus.BAD_REQUEST;
201	        BindingErrorsResponse errors = new BindingErrorsResponse();
202	        BindingResult bindingResult = e.getBindingResult();
203	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
204	        if (bindingResult.hasErrors()) {
205	            errors.addAllErrors(bindingResult);
206	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
207	                .map(fieldError -> {
208	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
209	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
210	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
211	                        fieldError.getField(),
212	                        defaultMessage,
213	                        rejectedValue);
214	                    return new ValidationMessageDto(message)
215	                        .putAdditionalProperty("field", fieldError.getField())
216	                        .putAdditionalProperty("rejectedValue", rejectedValue)
217	                        .putAdditionalProperty("defaultMessage", defaultMessage);
218	                })
219	                .toList();
220	            logger.debug("Validation error at {} {}: {}",
221	                request.getMethod(),
222	                request.getRequestURI(),
223	                bindingResult.getFieldErrors());
224	            List<String> errorFields = bindingResult.getFieldErrors().stream()
225	                .map(FieldError::getField)
226	                .distinct()
227	                .toList();
228	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
229	            detail.setProperty("errors", errorFields);
230	            return ResponseEntity.status(status).body(detail);
231	        }
232	        return ResponseEntity.status(status).body(detail);
233	    }
234	
235	}
