240	    @Override
241	    @Transactional
242	    public void saveOwner(Owner owner) throws DataAccessException {
243	        if (owner.getTelephone() != null) {
244	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
245	        }
246	        if (owner.getEmail() != null) {
247	            owner.setEmail(normalizeEmail(owner.getEmail()));
248	        }
249	        if (owner.getAddress() != null) {
250	            owner.setAddress(normalizeAddress(owner.getAddress()));
251	        }
252	        if (owner.getRegistrationDate() == null) {
253	            owner.setRegistrationDate(LocalDate.now());
254	        }
255	        if (owner.getCustomerCode() == null) {
256	            owner.setCustomerCode(generateCustomerCode(owner));
257	        }
258	        if (owner.isNew()) {
259	            owner.setNamesakeCount(countNamesakes(owner));
260	            assertCityCapacity(owner);
261	        }
262	        assertTelephoneUnique(owner, owner.getTelephone());
263	        List<Owner> household = findHouseholdMembers(owner);
264	        assertHouseholdAllowed(owner, household);
265	        assignHousehold(owner, household);
266	        ownerRepository.save(owner);
267	    }
268	
269	    /**
270	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
271	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
272	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
273	     * one more than the number of owners already in that city.
274	     */
275	    private String generateCustomerCode(Owner owner) {
276	        String cityPrefix = prefix3(owner.getCity());
277	        String lastNamePrefix = prefix3(owner.getLastName());
278	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
279	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
280	    }
281	
282	    private static String prefix3(String value) {
283	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
284	    }
285	
286	    /** Maximum number of owners permitted in a single city. */
287	    private static final long CITY_OWNER_LIMIT = 50L;
288	
289	    /**
290	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
291	     * more owners, so no city can grow beyond the capacity limit.
292	     *
293	     * @throws CityOwnerLimitException if the owner's city is already at capacity
294	     */
295	    private void assertCityCapacity(Owner owner) {
296	        if (owner.getCity() == null) {
297	            return;
298	        }
299	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
300	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
301	        }
302	    }
303	
304	    private long countOwnersInCity(String city) {
305	        String normalized = normalizeHouseholdValue(city);
306	        return ownerRepository.findAll().stream()
307	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
308	                .count();
309	    }
310	
311	    /**
312	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
313	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
314	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
315	     * that already existed before this create.
316	     */
317	    private int countNamesakes(Owner owner) {
318	        String firstName = normalizeHouseholdValue(owner.getFirstName());
319	        String lastName = normalizeHouseholdValue(owner.getLastName());
320	        int count = 0;
321	        for (Owner existing : ownerRepository.findAll()) {
322	            if (!existing.getId().equals(owner.getId())
323	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
324	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
325	                count++;
326	            }
327	        }
328	        return count;
329	    }
330	
331	    private static String normalizeEmail(String email) {
332	        return email == null ? null : email.toLowerCase(Locale.ROOT);
333	    }
334	
335	    /** Common street-type abbreviations expanded during address normalization. */
336	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
337	        "ST", "STREET",
338	        "RD", "ROAD",
339	        "AVE", "AVENUE");
340	
341	    /**
342	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
343	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
344	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
345	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
346	     * form.
347	     */
348	    private static String normalizeAddress(String address) {
349	        if (address == null) {
350	            return null;
351	        }
352	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
353	        if (collapsed.isEmpty()) {
354	            return "";
355	        }
356	        String[] tokens = collapsed.split(" ");
357	        StringBuilder sb = new StringBuilder(collapsed.length());
358	        for (int i = 0; i < tokens.length; i++) {
359	            if (i > 0) {
360	                sb.append(' ');
361	            }
362	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
363	        }
364	        return sb.toString();
365	    }
366	
367	    private static String normalizeTelephone(String telephone) {
368	        return telephone == null ? null : E164Telephone.toE164(telephone);
369	    }
370	
371	    /**
372	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
373	     * other owner, so no two owners can share a telephone number.
374	     *
375	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
376	     */
377	    private void assertTelephoneUnique(Owner owner, String normalized) {
378	        if (normalized == null || normalized.isEmpty()) {
379	            return;
380	        }
381	        for (Owner existing : ownerRepository.findAll()) {
382	            if (!existing.getId().equals(owner.getId())
383	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
384	                throw new DuplicateTelephoneException(normalized);
385	            }
386	        }
387	    }
388	
389	    /**
390	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
391	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
392	     * members of the household it would join. Returns an empty list for an update to an existing
393	     * owner or when either household value is blank, so household rules only apply to genuine new
394	     * members.
395	     */
396	    private List<Owner> findHouseholdMembers(Owner owner) {
397	        if (!owner.isNew()) {
398	            return List.of();
399	        }
400	        String lastName = normalizeHouseholdValue(owner.getLastName());
401	        String address = normalizeHouseholdAddress(owner.getAddress());
402	        if (lastName.isEmpty() || address.isEmpty()) {
403	            return List.of();
404	        }
405	        List<Owner> household = new ArrayList<>();
406	        for (Owner existing : ownerRepository.findAll()) {
407	            if (!existing.getId().equals(owner.getId())
408	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
409	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
410	                household.add(existing);
411	            }
412	        }
413	        return household;
414	    }
415	
416	    /**
417	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
418	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
419	     * without side effects otherwise.
420	     *
421	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
422	     *                                     the request does not acknowledge the shared household
423	     */
424	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
425	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
426	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
427	        }
428	    }
429	
430	    /**
431	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
432	     * owner and every matching existing member that lacks one are given the same stable
433	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
434	     * is empty.
435	     */
436	    private void assignHousehold(Owner owner, List<Owner> household) {
437	        if (household.isEmpty()) {
438	            return;
439	        }
440	        String householdId = resolveHouseholdId(owner, household);
441	        owner.setHouseholdId(householdId);
442	        for (Owner existing : household) {
443	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
444	                existing.setHouseholdId(householdId);
445	                ownerRepository.save(existing);
446	            }
447	        }
448	    }
449	
450	    /**
451	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
452	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
453	     * joining {@code owner}'s normalized lastName and address.
454	     */
455	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
456	        for (Owner existing : household) {
457	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
458	                return existing.getHouseholdId();
459	            }
460	        }
461	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
462	            normalizeHouseholdAddress(owner.getAddress()));
463	    }
464	
465	    /**
466	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
467	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
468	     * household deterministically share the same identifier.
469	     */
470	    private static String generateHouseholdId(String lastName, String address) {
471	        try {
472	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
473	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
474	            StringBuilder sb = new StringBuilder();
475	            for (int i = 0; i < 6; i++) {
476	                sb.append(String.format("%02X", hash[i]));
477	            }
478	            return "HH-" + sb;
479	        } catch (NoSuchAlgorithmException e) {
480	            throw new IllegalStateException("SHA-256 not available", e);
481	        }
482	    }
483	
484	    /**
485	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
486	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
487	     */
488	    private static String normalizeHouseholdValue(String value) {
489	        if (value == null) {
490	            return "";
491	        }
492	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
493	    }
494	
495	    /**
496	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
497	     * form (never {@code null}), so duplicate detection and the shared household id compare
498	     * addresses using the same normalized representation that is stored and returned.
499	     */
500	    private static String normalizeHouseholdAddress(String address) {
501	        String normalized = normalizeAddress(address);
502	        return normalized == null ? "" : normalized;
503	    }
504	
505	    @Override
506	    @Transactional(readOnly = true)
507	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
508	        return ownerRepository.findByLastName(lastName);
509	    }
510	
511	    @Override
512	    @Transactional(readOnly = true)
513	    public Collection<Visit> findVisitsByPetId(int petId) {
514	        return visitRepository.findByPetId(petId);
515	    }
516	
517	    @Override
518	    @Transactional(readOnly = true)
519	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
520	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
521	    }
522	
523	    private <T> T findEntityById(Supplier<T> supplier) {
524	        try {
525	            return supplier.get();
526	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
527	            // Just ignore not found exceptions for Jdbc/Jpa realization
528	            return null;
529	        }
530	    }
531	
532	}
